def _psi_1d(reference: np.ndarray, current: np.ndarray, bins: int = 10) -> float:
    """PSI for a single feature using quantile bins taken from the reference."""
    ref = np.asarray(reference, dtype=float).ravel()
    cur = np.asarray(current, dtype=float).ravel()
    quantiles = np.linspace(0, 1, bins + 1)
    edges = np.unique(np.quantile(ref, quantiles))
    if len(edges) < 2:
        edges = np.array([ref.min() - 1e-9, ref.max() + 1e-9])
    edges = np.asarray(edges, dtype=float)
    edges[0], edges[-1] = -np.inf, np.inf
    ref_hist, _ = np.histogram(ref, bins=edges)
    cur_hist, _ = np.histogram(cur, bins=edges)
    ref_p = np.clip(ref_hist / max(ref_hist.sum(), 1), 1e-6, None)
    cur_p = np.clip(cur_hist / max(cur_hist.sum(), 1), 1e-6, None)
    return float(np.sum((cur_p - ref_p) * np.log(cur_p / ref_p)))


def psi(reference: np.ndarray, current: np.ndarray, bins: int = 10):
    """Population Stability Index per feature (columns of the design matrix)."""
    ref = np.asarray(reference, dtype=float)
    cur = np.asarray(current, dtype=float)
    if ref.ndim == 1:
        return _psi_1d(ref, cur, bins)
    return np.array(
        [_psi_1d(ref[:, j], cur[:, j], bins) for j in range(ref.shape[1])]
    )

